/*
 * A011691  A binary m-sequence: expansion of reciprocal of x^7+x^6+x^5+x^2+1.
 * https://oeis.org/A011691
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = a(n-2) XOR a(n-5) XOR a(n-6) XOR a(n-7) * with initial
 *            terms a(0)=a(1)=a(2)=a(3)=a(4)=a(5)=0 and a(6)=1. * This defines
 *            the binary m‑sequence generated by the * reciprocal of
 *            x^7+x^6+x^5+x^2+1, which is 127‑periodic
 * Range:     u8 n <= 1000, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>

seq_t a(idx_t n)
{
    /* 127‑cycle (2^7−1).  Pre‑compute it once. */
    static seq_t cycle[127];
    static bool init = false;

    if (!init) {
        /* Build the period.  The first six terms are 0, the seventh is 1,
           and from n=7 on we use the recurrence. */
        for (idx_t i = 0; i < 127; ++i) {
            if (i <= 5) {
                cycle[i] = 0;                 /* a(0) … a(5) */
            } else if (i == 6) {
                cycle[i] = 1;                 /* a(6) */
            } else {
                cycle[i] =
                    cycle[i - 2] ^ cycle[i - 5] ^ cycle[i - 6] ^ cycle[i - 7];
            }
        }
        init = true;
    }

    return cycle[n % 127];
}
